begin;

create type public.vat_treatment as enum ('standard','zero_rated','exempt','out_of_scope');
create type public.vat_return_status as enum ('draft','submitted');

create table public.vat_tax_codes(
 id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete restrict,
 code text not null,name text not null,treatment public.vat_treatment not null,rate_bps integer not null,
 input_recoverable boolean not null default true,output_chargeable boolean not null default true,active boolean not null default true,
 effective_from date not null,effective_to date,created_by uuid not null references auth.users(id) on delete restrict,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 constraint vat_tax_code_format check(code~'^[A-Z0-9][A-Z0-9_-]{1,19}$'),constraint vat_tax_code_name check(char_length(btrim(name)) between 2 and 120),
 constraint vat_tax_code_rate check(rate_bps between 0 and 10000 and ((treatment='standard' and rate_bps>0)or(treatment<>'standard' and rate_bps=0))),
 constraint vat_tax_code_dates check(effective_to is null or effective_to>=effective_from),unique(academy_id,code,effective_from)
);
create index vat_tax_codes_academy_active_idx on public.vat_tax_codes(academy_id,active,effective_from,effective_to);create index vat_tax_codes_created_by_idx on public.vat_tax_codes(created_by);

alter table public.invoices add column vat_tax_code_id uuid references public.vat_tax_codes(id) on delete restrict,add column net_amount_minor integer,add column tax_amount_minor integer;
update public.invoices set net_amount_minor=amount_minor,tax_amount_minor=0;
alter table public.invoices alter column net_amount_minor set not null,alter column tax_amount_minor set not null,alter column tax_amount_minor set default 0;
alter table public.invoices add constraint invoices_vat_amounts check(net_amount_minor>=0 and tax_amount_minor>=0 and net_amount_minor+tax_amount_minor=amount_minor);
create index invoices_vat_code_idx on public.invoices(vat_tax_code_id) where vat_tax_code_id is not null;

alter table public.supplier_invoice_financials add column vat_tax_code_id uuid references public.vat_tax_codes(id) on delete restrict,add column net_amount_minor bigint,add column tax_amount_minor bigint;
update public.supplier_invoice_financials set net_amount_minor=amount_minor,tax_amount_minor=0;
alter table public.supplier_invoice_financials alter column net_amount_minor set not null,alter column tax_amount_minor set not null,alter column tax_amount_minor set default 0;
alter table public.supplier_invoice_financials add constraint supplier_invoice_vat_amounts check(net_amount_minor>=0 and tax_amount_minor>=0 and net_amount_minor+tax_amount_minor=amount_minor);
create index supplier_invoice_financials_vat_code_idx on public.supplier_invoice_financials(vat_tax_code_id) where vat_tax_code_id is not null;

create table public.vat_returns(
 id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete restrict,
 period_starts_on date not null,period_ends_on date not null,currency text not null,
 output_net_minor bigint not null default 0,output_vat_minor bigint not null default 0,input_net_minor bigint not null default 0,input_vat_minor bigint not null default 0,
 net_vat_minor bigint not null default 0,unclassified_sales integer not null default 0,unclassified_purchases integer not null default 0,
 status public.vat_return_status not null default 'draft',transaction_snapshot jsonb not null default '{}'::jsonb,
 generated_by uuid not null references auth.users(id) on delete restrict,generated_at timestamptz not null default now(),
 submitted_by uuid references auth.users(id) on delete restrict,submitted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 constraint vat_return_dates check(period_ends_on>=period_starts_on and period_ends_on-period_starts_on<=366),constraint vat_return_currency check(currency~'^[A-Z]{3}$'),
 constraint vat_return_submission check((status='submitted')=(submitted_by is not null and submitted_at is not null)),unique(academy_id,period_starts_on,period_ends_on,currency)
);
create index vat_returns_academy_period_idx on public.vat_returns(academy_id,currency,period_ends_on desc);create index vat_returns_generated_by_idx on public.vat_returns(generated_by);create index vat_returns_submitted_by_idx on public.vat_returns(submitted_by) where submitted_by is not null;

alter table public.vat_tax_codes enable row level security;alter table public.vat_returns enable row level security;
revoke all on public.vat_tax_codes,public.vat_returns from public,anon,authenticated;
grant select,insert,update on public.vat_tax_codes,public.vat_returns to authenticated;
grant select,insert,update,delete on public.vat_tax_codes,public.vat_returns to service_role;
grant usage on type public.vat_treatment,public.vat_return_status to authenticated;
create policy vat_tax_codes_read_administrators on public.vat_tax_codes for select to authenticated using((select private.is_platform_administrator()));
create policy vat_tax_codes_insert_administrators on public.vat_tax_codes for insert to authenticated with check((select private.is_platform_administrator())and created_by=(select auth.uid()));
create policy vat_tax_codes_update_administrators on public.vat_tax_codes for update to authenticated using((select private.is_platform_administrator()))with check((select private.is_platform_administrator()));
create policy vat_returns_read_administrators on public.vat_returns for select to authenticated using((select private.is_platform_administrator()));
create policy vat_returns_insert_administrators on public.vat_returns for insert to authenticated with check((select private.is_platform_administrator())and generated_by=(select auth.uid()));
create policy vat_returns_update_administrators on public.vat_returns for update to authenticated using((select private.is_platform_administrator()))with check((select private.is_platform_administrator()));

create function public.create_vat_tax_code(target_academy_id uuid,target_code text,target_name text,target_treatment public.vat_treatment,target_rate_bps integer,target_input_recoverable boolean,target_output_chargeable boolean,target_effective_from date,target_effective_to date)
returns uuid language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());new_id uuid;begin if actor is null or not private.is_platform_administrator()then raise exception 'platform administrator access required' using errcode='42501';end if;if upper(btrim(target_code))!~'^[A-Z0-9][A-Z0-9_-]{1,19}$' or char_length(btrim(target_name))not between 2 and 120 or target_rate_bps not between 0 and 10000 or ((target_treatment='standard')<>(target_rate_bps>0))or target_effective_to<target_effective_from then raise exception 'invalid VAT tax code' using errcode='22023';end if;insert into public.vat_tax_codes(academy_id,code,name,treatment,rate_bps,input_recoverable,output_chargeable,effective_from,effective_to,created_by)values(target_academy_id,upper(btrim(target_code)),btrim(target_name),target_treatment,target_rate_bps,target_input_recoverable,target_output_chargeable,target_effective_from,target_effective_to,actor)returning id into new_id;perform public.write_audit_event(target_academy_id,'vat.tax_code_created','vat_tax_code',new_id,jsonb_build_object('code',upper(btrim(target_code)),'treatment',target_treatment,'rate_bps',target_rate_bps));return new_id;end;$$;

create function public.classify_customer_invoice_vat(target_invoice_id uuid,target_tax_code_id uuid)
returns boolean language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());scoped public.invoices%rowtype;tax public.vat_tax_codes%rowtype;tax_minor integer;tax_date date;begin if actor is null or not private.is_platform_administrator()then raise exception 'platform administrator access required' using errcode='42501';end if;select * into scoped from public.invoices where id=target_invoice_id for update;select * into tax from public.vat_tax_codes where id=target_tax_code_id;tax_date:=scoped.issued_at::date;if scoped.id is null or tax.id is null or scoped.academy_id<>tax.academy_id or not tax.active or tax_date<tax.effective_from or(tax.effective_to is not null and tax_date>tax.effective_to)or scoped.status in('void','refunded')or not tax.output_chargeable then raise exception 'invoice VAT classification is invalid' using errcode='23514';end if;if exists(select 1 from public.vat_returns where academy_id=scoped.academy_id and currency=scoped.currency and status='submitted' and tax_date between period_starts_on and period_ends_on)then raise exception 'submitted VAT period is locked' using errcode='23514';end if;tax_minor:=case when tax.rate_bps=0 then 0 else round(scoped.amount_minor*tax.rate_bps/(10000.0+tax.rate_bps))::integer end;update public.invoices set vat_tax_code_id=tax.id,tax_amount_minor=tax_minor,net_amount_minor=amount_minor-tax_minor,updated_at=now()where id=scoped.id;perform public.write_audit_event(scoped.academy_id,'vat.customer_invoice_classified','invoice',scoped.id,jsonb_build_object('tax_code_id',tax.id,'tax_amount_minor',tax_minor));return true;end;$$;

create function public.classify_supplier_invoice_vat(target_invoice_id uuid,target_tax_code_id uuid)
returns boolean language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());scoped public.supplier_invoices%rowtype;financial public.supplier_invoice_financials%rowtype;tax public.vat_tax_codes%rowtype;tax_minor bigint;begin if actor is null or not private.is_platform_administrator()then raise exception 'platform administrator access required' using errcode='42501';end if;select * into scoped from public.supplier_invoices where id=target_invoice_id for update;select * into financial from public.supplier_invoice_financials where invoice_id=target_invoice_id for update;select * into tax from public.vat_tax_codes where id=target_tax_code_id;if scoped.id is null or financial.invoice_id is null or tax.id is null or scoped.academy_id<>tax.academy_id or not tax.active or scoped.issued_on<tax.effective_from or(tax.effective_to is not null and scoped.issued_on>tax.effective_to)or scoped.status='void' or not tax.input_recoverable then raise exception 'supplier VAT classification is invalid' using errcode='23514';end if;if exists(select 1 from public.vat_returns where academy_id=scoped.academy_id and currency=financial.currency and status='submitted' and scoped.issued_on between period_starts_on and period_ends_on)then raise exception 'submitted VAT period is locked' using errcode='23514';end if;tax_minor:=case when tax.rate_bps=0 then 0 else round(financial.amount_minor*tax.rate_bps/(10000.0+tax.rate_bps))::bigint end;update public.supplier_invoice_financials set vat_tax_code_id=tax.id,tax_amount_minor=tax_minor,net_amount_minor=amount_minor-tax_minor,updated_by=actor,updated_at=now()where invoice_id=scoped.id;perform public.write_audit_event(scoped.academy_id,'vat.supplier_invoice_classified','supplier_invoice',scoped.id,jsonb_build_object('tax_code_id',tax.id,'tax_amount_minor',tax_minor));return true;end;$$;

create function public.generate_vat_return(target_academy_id uuid,target_period_starts_on date,target_period_ends_on date,target_currency text)
returns uuid language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());normalized_currency text:=upper(btrim(target_currency));return_id uuid;output_net bigint;output_tax bigint;input_net bigint;input_tax bigint;missing_sales integer;missing_purchases integer;snapshot jsonb;begin if actor is null or not private.is_platform_administrator()then raise exception 'platform administrator access required' using errcode='42501';end if;if target_period_ends_on<target_period_starts_on or target_period_ends_on-target_period_starts_on>366 or normalized_currency!~'^[A-Z]{3}$'then raise exception 'invalid VAT return period' using errcode='22023';end if;if exists(select 1 from public.vat_returns where academy_id=target_academy_id and period_starts_on=target_period_starts_on and period_ends_on=target_period_ends_on and currency=normalized_currency and status='submitted')then raise exception 'submitted VAT return is locked' using errcode='23514';end if;select coalesce(sum(net_amount_minor),0),coalesce(sum(tax_amount_minor),0),count(*)filter(where vat_tax_code_id is null)into output_net,output_tax,missing_sales from public.invoices where academy_id=target_academy_id and currency=normalized_currency and issued_at::date between target_period_starts_on and target_period_ends_on and status in('issued','overdue','paid');select coalesce(sum(financial.net_amount_minor),0),coalesce(sum(financial.tax_amount_minor),0),count(*)filter(where financial.vat_tax_code_id is null)into input_net,input_tax,missing_purchases from public.supplier_invoices invoice join public.supplier_invoice_financials financial on financial.invoice_id=invoice.id where invoice.academy_id=target_academy_id and financial.currency=normalized_currency and invoice.issued_on between target_period_starts_on and target_period_ends_on and invoice.status in('approved','paid');snapshot:=jsonb_build_object('generated_at',now(),'sales',coalesce((select jsonb_agg(jsonb_build_object('id',id,'invoice_number',invoice_number,'net_minor',net_amount_minor,'vat_minor',tax_amount_minor,'tax_code_id',vat_tax_code_id)order by issued_at)from public.invoices where academy_id=target_academy_id and currency=normalized_currency and issued_at::date between target_period_starts_on and target_period_ends_on and status in('issued','overdue','paid')),'[]'::jsonb),'purchases',coalesce((select jsonb_agg(jsonb_build_object('id',invoice.id,'invoice_number',invoice.invoice_number,'net_minor',financial.net_amount_minor,'vat_minor',financial.tax_amount_minor,'tax_code_id',financial.vat_tax_code_id)order by invoice.issued_on)from public.supplier_invoices invoice join public.supplier_invoice_financials financial on financial.invoice_id=invoice.id where invoice.academy_id=target_academy_id and financial.currency=normalized_currency and invoice.issued_on between target_period_starts_on and target_period_ends_on and invoice.status in('approved','paid')),'[]'::jsonb));insert into public.vat_returns(academy_id,period_starts_on,period_ends_on,currency,output_net_minor,output_vat_minor,input_net_minor,input_vat_minor,net_vat_minor,unclassified_sales,unclassified_purchases,transaction_snapshot,generated_by)values(target_academy_id,target_period_starts_on,target_period_ends_on,normalized_currency,output_net,output_tax,input_net,input_tax,output_tax-input_tax,missing_sales,missing_purchases,snapshot,actor)on conflict(academy_id,period_starts_on,period_ends_on,currency)do update set output_net_minor=excluded.output_net_minor,output_vat_minor=excluded.output_vat_minor,input_net_minor=excluded.input_net_minor,input_vat_minor=excluded.input_vat_minor,net_vat_minor=excluded.net_vat_minor,unclassified_sales=excluded.unclassified_sales,unclassified_purchases=excluded.unclassified_purchases,transaction_snapshot=excluded.transaction_snapshot,generated_by=actor,generated_at=now(),updated_at=now()returning id into return_id;perform public.write_audit_event(target_academy_id,'vat.return_generated','vat_return',return_id,jsonb_build_object('period_starts_on',target_period_starts_on,'period_ends_on',target_period_ends_on,'currency',normalized_currency,'net_vat_minor',output_tax-input_tax));return return_id;end;$$;

create function public.submit_vat_return(target_return_id uuid)
returns boolean language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());scoped public.vat_returns%rowtype;begin if actor is null or not private.is_platform_administrator()then raise exception 'platform administrator access required' using errcode='42501';end if;select * into scoped from public.vat_returns where id=target_return_id for update;if not found or scoped.status='submitted'then raise exception 'draft VAT return required' using errcode='23514';end if;perform public.generate_vat_return(scoped.academy_id,scoped.period_starts_on,scoped.period_ends_on,scoped.currency);select * into scoped from public.vat_returns where id=target_return_id for update;if scoped.unclassified_sales>0 or scoped.unclassified_purchases>0 then raise exception 'classify every VAT transaction before submission' using errcode='23514';end if;update public.vat_returns set status='submitted',submitted_by=actor,submitted_at=now(),updated_at=now()where id=scoped.id;perform public.write_audit_event(scoped.academy_id,'vat.return_submitted','vat_return',scoped.id,jsonb_build_object('period_starts_on',scoped.period_starts_on,'period_ends_on',scoped.period_ends_on,'currency',scoped.currency,'net_vat_minor',scoped.net_vat_minor));return true;end;$$;

revoke all on function public.create_vat_tax_code(uuid,text,text,public.vat_treatment,integer,boolean,boolean,date,date),public.classify_customer_invoice_vat(uuid,uuid),public.classify_supplier_invoice_vat(uuid,uuid),public.generate_vat_return(uuid,date,date,text),public.submit_vat_return(uuid) from public,anon,authenticated;
grant execute on function public.create_vat_tax_code(uuid,text,text,public.vat_treatment,integer,boolean,boolean,date,date),public.classify_customer_invoice_vat(uuid,uuid),public.classify_supplier_invoice_vat(uuid,uuid),public.generate_vat_return(uuid,date,date,text),public.submit_vat_return(uuid) to authenticated;

commit;
